head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Workflow > P > description]<br/>Workflow 모듈에 대한 설명을 설정합니다.",
    "validation" : [
        "Workflow 모듈의 용도나 처리 내용에 대한 설명을 문자열로 설정할 수 있어야 합니다.",
        "description 속성은 메타 데이터 성격의 속성이며 Workflow 모듈의 동작에 영향을 미치지 않아야 합니다.",
        "스크립트로 Workflow 객체에 접근하여 값을 읽을 수 없어야 합니다."
    ]
}

scwin.gVar = {
    "status" : {}
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 실행 중인 Workflow 의 짧은 ID 반환 (페이지 scope 적용으로 실제 id 에는 prefix 가 붙음)
scwin.getShortId = function (fullId) {
    return (String(fullId).indexOf("wf_nodesc") > -1) ? "wf_nodesc" : "wf_desc";
};

// workflow step 의 마지막 function
scwin.wf_step_function = function (prevResult, wObj) {
};

// workflow 전체 콜백
scwin.wf_resolveCallback = function (wObj) {
    scwin.gVar.status[scwin.getShortId(wObj.id)] = "정상 완료";
};

scwin.wf_rejectCallback = function (wObj) {
    scwin.gVar.status[scwin.getShortId(wObj.id)] = "오류 종료";
};



// (1) description 설정값 확인 - XML 에 선언한 description 속성값
scwin.btn_checkDescription_onclick = function () {
    var wf1 = $p.getWorkflow("wf_desc");
    var wf2 = $p.getWorkflow("wf_nodesc");
    var d1 = wf1.xmlNode.getAttribute("description");
    var d2 = wf2.xmlNode.getAttribute("description");
    wf_body_bottom.getObj("scwin").setReturnValue("[설정값] XML 선언 속성값 - wf_desc : " + d1 + " / wf_nodesc(미설정) : " + d2);
};

// (2) description 설정 / 미설정 Workflow 를 각각 실행하여 동작 차이가 없음을 확인
scwin.btn_executeWorkflow_onclick = async function () {
    scwin.gVar.status = {};
    await $p.executeWorkflow("wf_desc");
    await $p.executeWorkflow("wf_nodesc");
    wf_body_bottom.getObj("scwin").setReturnValue("[실행] wf_desc(description 설정) : " + scwin.gVar.status["wf_desc"] + " / wf_nodesc(description 미설정) : " + scwin.gVar.status["wf_nodesc"]);
};

// (3) 스크립트로 Workflow 객체에 접근하여 description 값 읽기 시도
scwin.btn_readDescription_onclick = function () {
    var wf = $p.getWorkflow("wf_desc");
    wf_body_bottom.getObj("scwin").setReturnValue("[스크립트 접근] 반환된 Workflow 객체의 id : " + wf.id + " / 객체의 description : " + wf.description);
};
